import alchemy from "alchemy";
import { D1Database, TanStackStart } from "alchemy/cloudflare";

const app = await alchemy("logbook", {
  stage: process.env.ALCHEMY_STAGE ?? "prod",
});

// D1 database. Migrations in ./drizzle (generated by drizzle-kit) are applied
// on deploy and in local dev.
export const database = await D1Database("logbook-db", {
  name: "logbook-db",
  migrationsDir: "./drizzle",
  primaryLocationHint: "apac",
});

// TanStack Start worker served at logbook.alexanderar.com
export const worker = await TanStackStart("logbook-web", {
  domains: [{ domainName: "logbook.alexanderar.com" }],
  bindings: {
    DB: database,
    AI_API_KEY: alchemy.secret(process.env.AI_API_KEY ?? ""),
    AI_BASE_URL:
      process.env.AI_BASE_URL ?? "https://api.openai.com/v1",
    AI_MODEL: process.env.AI_MODEL ?? "gpt-4o-mini",
  },
});

await app.finalize();
